"""Local-only tests for social still generation; FFmpeg is mocked."""

import logging
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

import thumbnail
import share_thumbnail


class ShareThumbnailTests(unittest.TestCase):
    def setUp(self):
        # Keep generated artifacts inside the project and remove only fixtures
        # created by this test, which can be regenerated by rerunning it.
        self.work = Path(tempfile.mkdtemp(prefix="share-thumbnail-test-", dir=ROOT))
        self.video = self.work / "video"
        self.video.mkdir()
        self.source = self.video / "thumbnail_sdr.webp"
        self.source.write_bytes(b"fixture SDR still")
        self.log = logging.getLogger("test-share-thumbnail")
        self.root_patch = patch.object(thumbnail, "ROOT", self.work)
        self.root_patch.start()

    def tearDown(self):
        self.root_patch.stop()
        shutil.rmtree(self.work)

    @staticmethod
    def write_jpeg(cmd, **kwargs):
        Path(cmd[-1]).write_bytes(b"fixture JPEG")
        return subprocess.CompletedProcess(cmd, 0)

    def test_converts_full_sdr_still_with_aspect_ratio_preserved(self):
        (self.video / "thumbnail_sdr_720p.webp").write_bytes(b"small SDR fixture")
        with patch.object(thumbnail.subprocess, "run", side_effect=self.write_jpeg) as run:
            result = thumbnail.generate_share_thumbnail(self.video, self.log)
        self.assertEqual(result, self.video / "thumbnail_share.jpg")
        self.assertEqual(result.read_bytes(), b"fixture JPEG")
        cmd = run.call_args.args[0]
        self.assertEqual(cmd[cmd.index("-i") + 1], str(self.source))
        self.assertIn("force_original_aspect_ratio=decrease", cmd[cmd.index("-vf") + 1])
        self.assertEqual(cmd[cmd.index("-frames:v") + 1], "1")
        self.assertNotIn("-r", cmd)
        self.assertIn("-n", cmd)
        self.assertFalse(list(self.video.glob(".thumbnail_share-*.jpg")))

    def test_uses_small_sdr_still_when_full_still_is_missing(self):
        self.source.rename(self.video / "thumbnail_sdr_720p.webp")
        with patch.object(thumbnail.subprocess, "run", side_effect=self.write_jpeg) as run:
            thumbnail.generate_share_thumbnail(self.video, self.log)
        cmd = run.call_args.args[0]
        self.assertEqual(cmd[cmd.index("-i") + 1], str(self.video / "thumbnail_sdr_720p.webp"))

    def test_skips_existing_jpeg_by_default(self):
        output = self.video / "thumbnail_share.jpg"
        output.write_bytes(b"previous thumbnail")
        with patch.object(thumbnail.subprocess, "run") as run:
            self.assertEqual(thumbnail.generate_share_thumbnail(self.video, self.log), output)
        run.assert_not_called()
        self.assertEqual(output.read_bytes(), b"previous thumbnail")

    def test_replacement_archives_previous_jpeg_with_manifest(self):
        output = self.video / "thumbnail_share.jpg"
        output.write_bytes(b"previous thumbnail")
        with patch.object(thumbnail.subprocess, "run", side_effect=self.write_jpeg):
            self.assertEqual(thumbnail.generate_share_thumbnail(self.video, self.log, replace=True), output)
        archived = list((self.work / ".agent-trash").glob("*/video/thumbnail_share.jpg"))
        self.assertEqual(len(archived), 1)
        self.assertEqual(archived[0].read_bytes(), b"previous thumbnail")
        manifest = archived[0].parents[1] / "manifest.txt"
        self.assertIn("Original path: video/thumbnail_share.jpg", manifest.read_text(encoding="utf-8"))
        self.assertEqual(output.read_bytes(), b"fixture JPEG")

    def test_failed_conversion_preserves_existing_jpeg_and_cleans_generated_partial(self):
        output = self.video / "thumbnail_share.jpg"
        output.write_bytes(b"previous thumbnail")

        def fail(cmd, **kwargs):
            Path(cmd[-1]).write_bytes(b"partial generated JPEG")
            raise subprocess.CalledProcessError(1, cmd, stderr=b"conversion failed")

        with patch.object(thumbnail.subprocess, "run", side_effect=fail):
            self.assertIsNone(thumbnail.generate_share_thumbnail(self.video, self.log, replace=True))
        self.assertEqual(output.read_bytes(), b"previous thumbnail")
        self.assertFalse((self.work / ".agent-trash").exists())
        self.assertFalse(list(self.video.glob(".thumbnail_share-*.jpg")))

    def test_missing_sdr_still_never_uses_hdr_thumbnail(self):
        self.source.rename(self.video / "thumbnail_hdr.avif")
        with patch.object(thumbnail.subprocess, "run") as run:
            self.assertIsNone(thumbnail.generate_share_thumbnail(self.video, self.log))
        run.assert_not_called()

    def test_failed_final_move_restores_previous_jpeg(self):
        output = self.video / "thumbnail_share.jpg"
        output.write_bytes(b"previous thumbnail")
        original_rename = Path.rename

        def fail_generated_move(path, destination):
            if path.name.startswith(".thumbnail_share-"):
                raise OSError("fixture final move failure")
            return original_rename(path, destination)

        with patch.object(thumbnail.subprocess, "run", side_effect=self.write_jpeg), patch.object(
            Path, "rename", fail_generated_move
        ):
            self.assertIsNone(thumbnail.generate_share_thumbnail(self.video, self.log, replace=True))
        self.assertEqual(output.read_bytes(), b"previous thumbnail")

    def test_rejects_output_outside_project_before_conversion(self):
        with patch.object(thumbnail.subprocess, "run") as run:
            with self.assertRaisesRegex(ValueError, "inside the project"):
                thumbnail.generate_share_thumbnail(ROOT, self.log)
        run.assert_not_called()

    def test_backfill_cli_does_not_probe_or_upload_video(self):
        with patch.object(share_thumbnail, "ROOT", self.work), patch.object(
            thumbnail.subprocess, "run", side_effect=self.write_jpeg
        ) as run:
            self.assertEqual(share_thumbnail.main([str(self.video)]), 0)
        self.assertEqual(run.call_count, 1)
        self.assertEqual(Path(run.call_args.args[0][run.call_args.args[0].index("-i") + 1]).suffix, ".webp")

    def test_all_cli_processes_direct_video_directories(self):
        local = self.work / "web" / "local"
        local.mkdir(parents=True)
        self.video.rename(local / "id")
        with patch.object(share_thumbnail, "ROOT", self.work), patch.object(
            share_thumbnail, "LOCAL_DIR", local
        ), patch.object(
            thumbnail.subprocess, "run", side_effect=self.write_jpeg
        ):
            self.assertEqual(share_thumbnail.main(["--all"]), 0)
        self.assertTrue((local / "id" / "thumbnail_share.jpg").is_file())

    def test_upload_image_content_types(self):
        # Extract the literal mapping without importing upload's B2 dependencies
        # or loading optional local configuration.
        import ast
        tree = ast.parse((ROOT / "src" / "upload.py").read_text(encoding="utf-8"))
        assignment = next(node for node in tree.body if isinstance(node, ast.Assign) and any(
            isinstance(target, ast.Name) and target.id == "MIME_MAP" for target in node.targets
        ))
        mapping = ast.literal_eval(assignment.value)
        self.assertEqual(mapping[".jpg"], "image/jpeg")
        self.assertEqual(mapping[".webp"], "image/webp")
        self.assertEqual(mapping[".avif"], "image/avif")


if __name__ == "__main__":
    unittest.main()
